package com.apple.spark.rest;

import com.apple.spark.api.GetSubmissionStatusResponse;

public class GetSubmissionStatusResponseCacheValue {

    private final long createdTimeMillis = System.currentTimeMillis();

    private final GetSubmissionStatusResponse response;

    private final Throwable exception;

    public GetSubmissionStatusResponseCacheValue(GetSubmissionStatusResponse response) {
        this.response = response;
        this.exception = null;
    }

    public GetSubmissionStatusResponseCacheValue(Throwable exception) {
        this.response = null;
        this.exception = exception;
    }

    public GetSubmissionStatusResponse getResponse() {
        return response;
    }

    public Throwable getException() {
        return exception;
    }

    public long getCreatedTimeMillis() {
        return createdTimeMillis;
    }
}

